#include <bits/stdc++.h>
using namespace std;

void solve(){
    long long  n;
    cin >> n;
    long long res = 0;
    
    vector<long long> a(3*n);
    
    for(auto& it : a){
        cin >> it;
    }
    sort(a.begin() , a.end()) ; 
    reverse(a.begin(), a.end());
    vector<long long> pref(3*n+1) ; 
    for (int i = 0 ; i< 3*n ; i++) {
        pref[i+1] = pref[i] + a[i]; 
    }
    
    auto cmp = [&](long long x, long long y) {
        long long temp = 2LL*n - x + y;
        
        return 2LL*pref[temp] + pref[x - 3LL*y] + 3LL*pref[x];
    };
    
    
    for(auto i = n; i <= 3LL*n; i++){
        long long left = max(0LL, i - 2LL*n);
        long long right = (i - n) / 2;
        
        long long l = left, r = right;
        
        long long idx = left;
        
        while(l <= r){
            long long mid = l + (r - l) / 2;
            
            if(mid < right && cmp(i, mid+1) >= cmp(i, mid)){
                l = mid + 1;
                idx = mid + 1;
            }
            else{
                r = mid - 1;
            }
        }
        
        long long start = max(left, idx - 2);
        long long end = min(right, idx + 2);
        
        for(int j = start; j <= end; j++){
            res = max(res, cmp(i, j));
        }
    }
    cout << res << endl;
    
    
}

int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--){
        solve();
    }
    return 0;
}
